CREATE TABLE IF NOT EXISTS STUDENTS (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(15) NOT NULL, surname VARCHAR(25) NOT NULL, faculty VARCHAR(20) NOT NULL, age INT NOT NULL);
CREATE TABLE IF NOT EXISTS STUDY_GROUPS (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, group_name VARCHAR(20) NOT NULL UNIQUE, specialty VARCHAR(80) NOT NULL, course INT NOT NULL, curator VARCHAR(80) NOT NULL);